import React, { useEffect, useState } from 'react'
import { connect } from 'react-redux'
import { Select } from 'antd'
import policyActions from '../../../../redux/policy/actions'

const { Option } = Select

const PremiumV2Picker = ({
  productCode,
  packageCode,
  value,
  onChange,
  getFormulaAttribute,
  getFormulaAttributeData,
  getFormulaAttributeMessage
}) => {
  const [options, setOptions] = useState([])

  useEffect(() => {
    if (productCode && packageCode) {
      getFormulaAttribute({ productCode, packageCode, offset: 0, limit: 100 })
    }
  }, [productCode, packageCode])

  useEffect(() => {
    if (getFormulaAttributeMessage && getFormulaAttributeMessage.toLowerCase().includes('success')) {
      const list = getFormulaAttributeData?.data || []
      const mapped = Array.isArray(list)
        ? list.map((item) => ({
            id: String(item.ID),
            variable: item.variable,
            attribute_name: item.product_attribute_name
          }))
        : []
      setOptions(mapped)
    }
  }, [getFormulaAttributeData, getFormulaAttributeMessage])

  const selectedId = value !== undefined && value !== null ? String(value) : undefined
  const hasMatch = options.some((opt) => opt.id === selectedId)

  return (
    <Select
      style={{ width: '100%' }}
      placeholder='Select a Premium V2 variable'
      value={hasMatch ? selectedId : undefined}
      onChange={(selected) => onChange(selected !== undefined ? Number(selected) : undefined)}
      allowClear
    >
      {options.map((opt) => (
        <Option key={opt.id} value={opt.id}>
          {opt.variable} {opt.attribute_name ? `(${opt.attribute_name})` : ''}
        </Option>
      ))}
    </Select>
  )
}

export default connect(
  (state) => ({
    getFormulaAttributeData: state.Policy?.getFormulaAttributeData,
    getFormulaAttributeMessage: state.Policy?.getFormulaAttributeMessage
  }),
  {
    getFormulaAttribute: policyActions.getFormulaAttribute
  }
)(PremiumV2Picker)
