import React from 'react'
import { Input, Select, Button } from 'antd'
import { TagContainer, TncRowContainer } from '../commanComponent.style'

const TncSection = ({
  tncs = [],
  onAdd,
  onRemove,
  onUpdateText,
  onUpdateTags
}) => {
  return (
    <div>
      {tncs.map((tnc, index) => (
        <TncRowContainer key={index}>
          <div style={{ flex: 1 }}>
            <Input.TextArea
              value={tnc.text}
              onChange={(e) => onUpdateText(index, e.target.value)}
              placeholder='Enter terms and conditions'
              rows={2}
            />
          </div>
          <TagContainer>
            <Select
              mode='tags'
              placeholder='Add tags (press Enter or comma)'
              value={tnc.tags || []}
              onChange={(value) => {
                const cleaned = value
                  .map((v) => v.trim())
                  .filter(Boolean)
                  .filter((v, i, a) => a.indexOf(v) === i)
                onUpdateTags(index, cleaned)
              }}
              style={{ width: '100%' }}
              tokenSeparators={[',']}
              dropdownStyle={{ display: 'none' }}
              tagRender={(props) => {
                const { label, closable, onClose } = props
                return (
                  <span
                    style={{
                      backgroundColor: '#1890ff',
                      color: 'white',
                      borderRadius: '12px',
                      padding: '1px 8px',
                      fontSize: '12px',
                      marginRight: '4px',
                      marginBottom: '4px',
                      display: 'inline-flex',
                      alignItems: 'center'
                    }}
                  >
                    {label}
                    {closable && (
                      <span
                        style={{ marginLeft: '4px', cursor: 'pointer' }}
                        onClick={onClose}
                      >
                        ×
                      </span>
                    )}
                  </span>
                )
              }}
            />
            <Button type='danger' size='small' onClick={() => onRemove(index)}>
              Remove
            </Button>
          </TagContainer>
        </TncRowContainer>
      ))}

      <Button type='dashed' onClick={onAdd} block>
        Add TnC Row
      </Button>
    </div>
  )
}

export default TncSection
