import React, { useEffect, useState } from 'react'
import { Form, Input, Select, Switch, Button, Collapse, Icon } from 'antd'
import PremiumV2Picker from './PremiumV2Picker'
import {
  ActionsContainer,
  AddOnFormWrapper,
  ErrorText,
  GridContainer,
  Label,
  SwitchContainer
} from './commanComponent.style'
import TncSection from './Tags'

const { Option } = Select

const AddOnFormPage = ({
  form,
  editingRecord,
  onSave,
  onUpdate,
  onCancel,
  productCode,
  packageCode
}) => {
  const { validateFields } = form

  const [formValues, setFormValues] = useState({
    code: editingRecord?.code || '',
    name: editingRecord?.name || '',
    auto_apply: editingRecord?.auto_apply || false,
    allow_zero_result: editingRecord?.allow_zero_result || false,
    is_active: editingRecord?.is_active,
    include_in_premium: editingRecord?.include_in_premium || false,
    show_in_breakdown: editingRecord?.show_in_breakdown || false,
    formula_attribute_id: editingRecord?.formula_attribute_id || undefined
  })

  const [tncs, setTncs] = useState(editingRecord?.wordings || [])
  const [errors, setErrors] = useState({})

  const handleInputChange = (field, value) => {
    setFormValues((prev) => ({ ...prev, [field]: value }))
    if (errors[field]) {
      setErrors((prev) => {
        const newErrors = { ...prev }
        delete newErrors[field]
        return newErrors
      })
    }
  }

  const addTncRow = () => {
    setTncs([...tncs, { text: '', tags: [] }])
  }

  const removeTncRow = (index) => {
    setTncs(tncs.filter((_, i) => i !== index))
  }

  const updateTncText = (index, value) => {
    const newTncs = [...tncs]
    newTncs[index].text = value
    setTncs(newTncs)
  }

  const validate = () => {
    const newErrors = {}
    if (!formValues.code) newErrors.code = 'Code is required'
    if (!formValues.name || !formValues.name.trim()) {
      newErrors.name = 'Name is required'
    }
    if (!formValues.formula_attribute_id) {
      newErrors.formula_attribute_id = 'Premium V2 term is required'
    }
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = (e) => {
    e.preventDefault()

    validateFields(async (err) => {
      if (err) {
        console.error('Validation failed', err)
        return
      }

      if (!validate()) return

      const payload = {
        ...formValues,
        wordings: [...tncs],
        ...(editingRecord?.code && {
          key: editingRecord.key,
          no: editingRecord.no
        })
      }

      if (editingRecord?.code) {
        onUpdate(payload)
      } else {
        onSave(payload)
      }
    })
  }

  const handleUpdateTags = (index, tags) => {
    const newTncs = [...tncs]
    newTncs[index].tags = tags
    setTncs(newTncs)
  }

  useEffect(() => {
    if (editingRecord?.id) {
      setFormValues({
        code: editingRecord?.code || '',
        name: editingRecord?.name || '',
        auto_apply: editingRecord?.auto_apply || false,
        allow_zero_result: editingRecord?.allow_zero_result || false,
        is_active: editingRecord?.is_active,
        include_in_premium: editingRecord?.include_in_premium || false,
        show_in_breakdown: editingRecord?.show_in_breakdown || false,
        formula_attribute_id: editingRecord?.formula_attribute_id || undefined
      })
      setTncs(editingRecord?.wordings)
    }
  }, [editingRecord])

  return (
    <Form onSubmit={handleSubmit} layout='vertical'>
      <AddOnFormWrapper>
        <div className='header-wrapper'>
          <Button onClick={onCancel} style={{ marginRight: 8 }}>
            <Icon type='arrow-left' /> Back
          </Button>
          <h2>{editingRecord?.code ? 'Edit' : 'Add New'} Add-On</h2>
        </div>
        <Collapse
          defaultActiveKey={['addon', 'tnc', 'premium']}
          style={{ marginBottom: 24 }}
        >
          <Collapse.Panel header='Add-On Data' key='addon'>
            <GridContainer>
              <div>
                <Label>Code *</Label>
                <Input
                  value={formValues.code}
                  onChange={(e) => handleInputChange('code', e.target.value)}
                  placeholder='Enter Code'
                  disabled={editingRecord?.code}
                />
                {errors.code && <ErrorText>{errors.code}</ErrorText>}
              </div>

              <div>
                <Label>Name *</Label>
                <Input
                  value={formValues.name}
                  onChange={(e) => handleInputChange('name', e.target.value)}
                  placeholder='Enter name'
                />
                {errors.name && <ErrorText>{errors.name}</ErrorText>}
              </div>

              <SwitchContainer>
                <div>
                  <Label>Auto Apply</Label>
                  <Switch
                    checked={formValues.auto_apply}
                    onChange={(checked) =>
                      handleInputChange('auto_apply', checked)}
                    checkedChildren='Yes'
                    unCheckedChildren='No'
                  />
                </div>

                <div>
                  <Label>Allow Zero Result</Label>
                  <Switch
                    checked={formValues.allow_zero_result}
                    onChange={(checked) =>
                      handleInputChange('allow_zero_result', checked)}
                    checkedChildren='Yes'
                    unCheckedChildren='No'
                  />
                </div>

                <div>
                  <Label>Include in Premium</Label>
                  <Switch
                    checked={formValues.include_in_premium}
                    onChange={(checked) =>
                      handleInputChange('include_in_premium', checked)}
                    checkedChildren='Yes'
                    unCheckedChildren='No'
                  />
                </div>

                <div>
                  <Label>Show in Breakdown</Label>
                  <Switch
                    checked={formValues.show_in_breakdown}
                    onChange={(checked) =>
                      handleInputChange('show_in_breakdown', checked)}
                    checkedChildren='Yes'
                    unCheckedChildren='No'
                  />
                </div>
              </SwitchContainer>

              <div>
                <Label>Status</Label>
                <Select
                  style={{ width: '100%' }}
                  value={formValues.is_active}
                  onChange={(value) => handleInputChange('is_active', value)}
                >
                  <Option value>Active</Option>
                  <Option value={false}>Inactive</Option>
                </Select>
              </div>
            </GridContainer>
          </Collapse.Panel>

          <Collapse.Panel header='Add-On TnC' key='tnc'>
            <TncSection
              tncs={tncs}
              onAdd={addTncRow}
              onRemove={removeTncRow}
              onUpdateText={updateTncText}
              onUpdateTags={(index, tags) => handleUpdateTags(index, tags)}
            />
          </Collapse.Panel>

          <Collapse.Panel header='Premium' key='premium'>
            <PremiumV2Picker
              productCode={productCode}
              packageCode={packageCode}
              value={formValues.formula_attribute_id}
              onChange={(value) => handleInputChange('formula_attribute_id', value)}
            />
            {errors.formula_attribute_id && <ErrorText>{errors.formula_attribute_id}</ErrorText>}
          </Collapse.Panel>
        </Collapse>

        <ActionsContainer>
          <Button onClick={onCancel} style={{ marginRight: 8 }}>
            Cancel
          </Button>
          <Button type='primary' htmlType='submit'>
            {editingRecord ? 'Update' : 'Save'}
          </Button>
        </ActionsContainer>
      </AddOnFormWrapper>
    </Form>
  )
}

const WrappedAddOnFormPage = Form.create({ name: 'addon_form' })(AddOnFormPage)

export default WrappedAddOnFormPage
