import { useHistory, useLocation, useParams } from 'react-router'
import AddOnFormPage from '../../components/AddOnFormPage'
import { useEffect, useState } from 'react'
import actions from '../../../../redux/productConfig/actions'
import { connect } from 'react-redux'
import { showNotification } from '../../../../../components/ShowNotification'

const AddonsPage = (props) => {
  const history = useHistory()
  const location = useLocation()
  const { id } = useParams()
  const {
    config_reference_id: configReferenceId,
    product_code: productCode,
    package_code: packageCode
  } = location.state || {}

  const [defaultData, setDefaultData] = useState(null)

  const handleSave = (data) => {
    if (!configReferenceId) {
      showNotification(
        'error',
        'Configuration Error',
        'Missing config reference ID'
      )
      return
    }
    props.createAddonActions({
      body: data,
      query: { addon_map_id: configReferenceId }
    })
  }

  const handleUpdate = (data) => {
    props.editAddonActions({
      body: data,
      query: { id: id, addon_map_id: configReferenceId }
    })
  }

  const handleCancel = () => {
    history.goBack()
  }

  useEffect(() => {
    if (props.createAddonMessage) {
      if (props.createAddonMessage === 'successful') {
        showNotification('success', 'Success', 'Add-on created successfully!')
        props.resetProductConfigRedux(['createAddonMessage'])
        setTimeout(() => {
          history.goBack()
        }, 500)
      } else {
        const errorMsg =
          props.createAddonMessage.message || 'Failed to create add-on'
        showNotification('error', 'Error', errorMsg)
      }
    }
  }, [props.createAddonMessage, history])

  useEffect(() => {
    if (props.editAddonMessage) {
      if (props.editAddonMessage === 'success') {
        showNotification('success', 'Success', 'Add-on updated successfully!')
        props.resetProductConfigRedux(['editAddonMessage'])
        props.getDetailsAddonData({ query: { id: id } })
      }
    }
  }, [props.editAddonMessage, history])

  useEffect(() => {
    if (!configReferenceId) {
      showNotification(
        'warning',
        'Invalid Navigation',
        'Missing configuration reference'
      )
      history.push('/product-config')
    }
  }, [configReferenceId, history])

  useEffect(() => {
    if (id) {
      props.getDetailsAddonData({ query: { id: id } })
    }
  }, [id])

  useEffect(() => {
    if (props?.detailsAddonData?.details?.details?.length > 0) {
      setDefaultData(props.detailsAddonData.details.details[0])
    }
  }, [props.detailsAddonData])

  return (
    <AddOnFormPage
      editingRecord={defaultData}
      onSave={handleSave}
      onUpdate={handleUpdate}
      onCancel={handleCancel}
      productCode={productCode}
      packageCode={packageCode}
    />
  )
}

const mapStateToProps = (state) => {
  return {
    createAddonData: state.ProductConfigurable?.createAddonData || [],
    createAddonMessage: state.ProductConfigurable?.createAddonMessage,
    detailsAddonData: state.ProductConfigurable?.getDetailAddonsData || [],
    detailsAddonMessage: state.ProductConfigurable?.getDetailAddonsMessage,
    editAddonData: state.ProductConfigurable?.editAddonData || [],
    editAddonMessage: state.ProductConfigurable?.editAddonMessage
  }
}

const mapDispatchToProps = (dispatch) => {
  return {
    createAddonActions: (payload) =>
      dispatch({ type: actions.CREATE_ADDON_REQUEST, payload }),
    getDetailsAddonData: (payload) =>
      dispatch({ type: actions.GET_DETAILS_ADDON_REQUEST, payload }),
    editAddonActions: (payload) =>
      dispatch({ type: actions.EDIT_ADDON_REQUEST, payload }),
    resetProductConfigRedux: (payload) =>
      dispatch({ type: actions.RESET_PRODUCT_CONFIG, payload })
  }
}

export default connect(mapStateToProps, mapDispatchToProps)(AddonsPage)
